mapper.select:
select a.id, a.code, a.advance_registration_id, a.material_id, a.material_name, a.material_code, a.rfid, a.batch_code, a.tray_id, a.location_id, a.status, ifnull(a.use_count,0) as use_count, a.weight, a.price, a.small_unit_count, a.detection_fail_type, a.detection_fail_remark, a.detection_fail_status, a.remark, a.rfid_head, a.create_time,
tu.name as unitName, tl.name as locationName,a.rfid_count
from t_material_detail a
left join t_material m on a.material_id = m.id
left join t_unit tu on m.unit_id = tu.id
left join t_location tl on a.location_id = tl.id

    inner join sys_user u on u.user_name = a.create_by and u.status = '0'
    inner join sys_dept d on u.dept_id = d.dept_id and d.status = '0'


    a.del_flag = '0'
     and a.code like concat('%', #{code}, '%')
     and a.advance_registration_id = #{advanceRegistrationId}
     and a.material_id = #{materialId}
     and a.material_name like concat('%', #{materialName}, '%')
     and a.material_code like concat('%', #{materialCode}, '%')
     and a.rfid = #{rfid}
     and a.batch_code like concat('%', #{batchCode}, '%')
     and a.tray_id = #{trayId}
     and a.status = #{status}
     and a.use_count = #{useCount}
     and a.weight = #{weight}
     and a.price = #{price}
     and a.small_unit_count = #{smallUnitCount}
     and a.detection_fail_type = #{detectionFailType}
     and a.detection_fail_remark = #{detectionFailRemark}
     and a.detection_fail_status = #{detectionFailStatus}
     and a.rfid_head like concat('%', #{rfidHead}, '%')

        and a.location_id is null
        and a.location_id is not null
        and (a.location_id = #{locationId} or a.location_id is null)
        and a.location_id = #{locationId}



${params.dataScope}
order by a.location_id desc, a.create_time desc

select a.material_id,a.batch_code,a.rfid,a.rfid_head,tm.`name` as materialName,a.rfid_count from t_material_detail a
inner join t_material tm on tm.id = a.material_id

    a.del_flag = '0' and a.status in ('0','1','4') and a.detection_fail_status = '1'
     and a.code like concat('%', #{code}, '%')
     and a.advance_registration_id = #{advanceRegistrationId}
     and a.material_id = #{materialId}
     and a.rfid = #{rfid}
     and a.batch_code = #{batchCode}
     and a.tray_id = #{trayId}
     and a.status = #{status}
     and a.detection_fail_status = #{detectionFailStatus}
     and a.rfid_head = #{rfidHead}

select a.id, a.material_name , a.material_id , a.material_code , a.rfid , a.batch_code , a.advance_registration_id, b.advance_delivery_id from t_material_detail a left join t_advance_delivery_detail b on a.advance_registration_id = b.id where a.detection_fail_status = '0' and a.del_flag = '0' and b.del_flag = '0'
and b.advance_delivery_id = #{deliveryId}
