select a.material_id , a.batch_code , a.location_id , count(*) as count from t_material_detail a where a.del_flag = '0' and a.rfid in
#{rfId}
group by a.material_id , a.batch_code, a.location_id

select count(*)
from t_material_detail a
left join t_advance_delivery_detail b on a.advance_registration_id = b.id
where a.del_flag = '0' and b.advance_delivery_id = #{deliveryId}
 and a.status = #{status}

select a.rfid_head, a.material_code, a.batch_code, tu.NAME as unitName, m.description, count(*) as detailCount from t_material_detail a left join t_material m on a.material_id = m.id left join t_unit tu on m.unit_id = tu.id where a.del_flag = '0'
#{rfidHead}
group by a.material_id , a.material_code , a.batch_code , a.rfid_head

SELECT t2.area_id,t1.material_id,t1.material_name,t1.material_code,t2.reservoir_id,t3.name as reservoir_name,SUM(t1.rfid_count) as rfid_count,
(SELECT create_time FROM t_check_delivery where area_id=t2.area_id and reservoir_id=t2.reservoir_id and material_id=t1.material_id ORDER BY create_time desc LIMIT 1) as last_check_time
from t_material_detail t1
left join t_tray tray on t1.tray_id = tray.id
LEFT JOIN t_location t2 on t1.location_id=t2.id
LEFT JOIN t_reservoir t3 on t2.reservoir_id=t3.id
WHERE t1.del_flag = '0' and t1.rfid_count !=0

    and t2.area_id=#{areaId}


    and t2.reservoir_id=#{reservoirId}


    and tray.tray_category=#{trayType} and t2.location_type != '1'


    and t1.material_name=#{entity.materialName}


    and t1.material_code=#{entity.materialCode}


    and t1.batch_code=#{entity.batchCode}


    and t1.location_id=#{entity.locationId}

GROUP BY t2.area_id,t2.reservoir_id,t3.name,t1.material_id,t1.material_name,t1.material_code
